import { Component } from '@angular/core';
import { DonationService } from '../services/donation.service';

@Component({
  selector: 'app-donate',
  templateUrl: './donate.component.html',
  styleUrls: ['./donate.component.css']
})
export class DonateComponent {

    donation = {
    name: '',
    email: '',
    amount: null
  };

  successMessage = '';
  errorMessage = '';
  loading = false;

  constructor(private donationService: DonationService) {}

  submitDonation(): void {

    this.successMessage = '';
    this.errorMessage = '';

    if (
      !this.donation.name ||
      !this.donation.email ||
      !this.donation.amount
    ) {
      this.errorMessage = 'Please fill in all fields.';
      return;
    }
    this.loading = true;

    this.donationService.createDonation(this.donation).subscribe({

      next: (response) => {

        console.log(response);

        this.successMessage =
          'Thank you! Your donation request has been received.';

        this.donation = {
          name: '',
          email: '',
          amount: null
        };

        this.loading = false;
      },

      error: (error) => {

        console.error(error);

        this.errorMessage =
          'Unable to process your donation request.';

        this.loading = false;
      }
    });
  }
}
